3	/**
4	 * OmniRoute CLI entry point.
5	 *
6	 * Special bypasses (handled before Commander):
7	 *   --version / -V (alone)    Fast-path: print the version and exit, skipping the
8	 *                             tsx/esm + polyfill imports, env-file loading, and
9	 *                             Commander's ~70-command registration entirely.
10	 *   --mcp                     Start MCP server over stdio
11	 *   reset-encrypted-columns   Recovery tool for broken encrypted credentials
12	 *   reset-password            Reset the admin/management password
13	 *
14	 * All other commands are routed through Commander (bin/cli/program.mjs).
15	 */
16	
17	import { existsSync, readFileSync } from "node:fs";
18	import { join, dirname } from "node:path";
19	import { fileURLToPath, pathToFileURL } from "node:url";
20	let updateNotifier = null;
21	try {
22	  updateNotifier = (await import("update-notifier")).default;
23	} catch {
24	  // update-notifier is optional in pruned standalone environments
25	}
26	import { isNativeBinaryCompatible } from "../scripts/build/native-binary-compat.mjs";
27	import { getNodeRuntimeSupport, getNodeRuntimeWarning } from "./nodeRuntimeSupport.mjs";
28	import { getDefaultDataDir } from "./cli/data-dir.mjs";
29	import { shouldProvisionStorageKey } from "./cli/utils/storageKeyProvision.mjs";
30	import { isVersionFastPath } from "./cli/utils/versionFastPath.mjs";
31	import { parseEnvValue } from "./cli/utils/parseEnvValue.mjs";
