39	const __filename = fileURLToPath(import.meta.url);
40	const __dirname = dirname(__filename);
41	const ROOT = join(__dirname, "..");
42	
43	// Fast-path a bare `--version`/`-V` query BEFORE the tsx/esm registration, the
44	// polyfill import, env-file loading, or Commander's command registration (~70
45	// modules — DB, providers, OAuth, etc.) run. None of that work is needed to answer
46	// "what version is this" — mirrors upstream 9router PR #2414 (fast-path help/version
47	// ahead of expensive self-heal hooks), adapted to OmniRoute's Commander CLI where the
48	// equivalent expensive work is eager command registration rather than npm-install-based
49	// runtime self-healing. `--help` is intentionally NOT fast-pathed here: its output is
50	// generated dynamically from every registered subcommand, so skipping registration
51	// would truncate the help text instead of just speeding it up.
52	if (isVersionFastPath(process.argv)) {
53	  const pkg = JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8"));
54	  console.log(pkg.version);
55	  process.exit(0);
56	}
57	
58	// Detect an unsupported Node.js runtime BEFORE the heavy `tsx/esm` import and
59	// Commander's ~70-command registration chain run. That chain pulls in `ora` ->
60	// the hoisted `string-width` package, whose module contains top-level ES2024
61	// Unicode-set (`v` flag) regex literals. On a Node/V8 build that predates
62	// `v`-flag support, those literals fail to even *parse*, throwing a bare
63	// `SyntaxError: Invalid regular expression flags` deep inside a transitive
64	// dependency instead of an actionable message (#12296). Skip this for the
65	// same read-only invocations `shouldProvisionStorageKey` already exempts
66	// (`--help`/`-h`, `help`/`completion`) — those still need the full command
67	// registry to render their output, so an incompatible runtime crashing there
68	// is a separate, pre-existing limitation this fix does not attempt to solve.
69	if (shouldProvisionStorageKey(process.argv)) {
70	  const nodeSupport = getNodeRuntimeSupport();
71	  if (!nodeSupport.nodeCompatible) {
72	    const runtimeWarning = getNodeRuntimeWarning() || "Unsupported Node.js runtime detected.";
73	    console.error(
74	      `\x1b[31m✖ Node.js ${nodeSupport.nodeVersion} is not supported.\x1b[0m\n` +
75	        `  ${runtimeWarning}\n` +
76	        `  Supported runtimes: ${nodeSupport.supportedDisplay}\n` +
77	        `  Recommended: Node.js ${nodeSupport.recommendedVersion}\n` +
78	        `  If you installed OmniRoute globally, run \`node -v\` and confirm \`omniroute\` is not resolving to\n` +
79	        `  a stale/distro-packaged \`nodejs\` binary (e.g. /usr/bin/node) instead of the version you expect —\n` +
80	        `  that mismatch is the most common cause even when package.json's engines range is correct.`
81	    );
82	    process.exit(1);
83	  }
84	}
