86	// MCP stdio transport uses stdout exclusively for JSON-RPC messages. Redirect
87	// console.log/warn to stderr before anything else runs — including the tsx/esm and
88	// polyfill imports below, since those (and their transitive module graphs, e.g. DB
89	// init) can themselves log during evaluation. Redirecting after those imports let
90	// early output leak straight into the JSON-RPC stream and corrupt it client-side
91	// (e.g. Claude Desktop: "Unexpected token 'D', \"[DB] Changi\"... is not valid JSON").
92	if (process.argv.includes("--mcp")) {
93	  const { Console } = await import("node:console");
94	  const stderrConsole = new Console({ stdout: process.stderr, stderr: process.stderr });
95	  console.log = stderrConsole.log.bind(stderrConsole);
96	  console.warn = stderrConsole.warn.bind(stderrConsole);
97	}
