99	// Register tsx so dynamic imports of .ts source files (referenced as .js per
100	// TypeScript conventions) resolve correctly. The build never emits .js for
101	// src/lib/cli-helper/, so tsx handles the .ts → .js resolution at runtime.
102	await import("tsx/esm");
103	await import("../open-sse/utils/setupPolyfill.ts");
104	
105	// #7791: tsx's tsconfig-path resolution does not apply when OmniRoute is
106	// installed globally (files live under node_modules/omniroute/), so bare
107	// `@/...` specifiers (declared in tsconfig.json paths as `@/* → ./src/*`)
108	// fail with ERR_MODULE_NOT_FOUND. Register an ESM resolve hook that maps
109	// `@/...` to absolute file URLs under <ROOT>/src/. Safe no-op in dev checkout
110	// (paths already resolve via tsconfig) and when ROOT has no `src/` dir.
111	const { registerAliasResolver } = await import("./aliasResolver.mjs");
112	await registerAliasResolver(ROOT);
