116	// install (storage.sqlite + server.env) to the CLI left those secrets undiscoverable —
117	// the CLI only ever looked for `.env`, so the STORAGE_ENCRYPTION_KEY needed to decrypt
118	// the migrated database was silently dropped (#7302). One-time, one-directory migration:
119	// if `<dataDir>/.env` is absent but `<dataDir>/server.env` is present, copy it to `.env`
120	// so it flows through the normal env-loading path below. Never overwrites an existing
121	// `.env` — an explicit `.env` always wins over a legacy `server.env`.
122	function migrateElectronServerEnv(dataDir) {
123	  try {
124	    const envPath = join(dataDir, ".env");
125	    const serverEnvPath = join(dataDir, "server.env");
126	    if (existsSync(envPath) || !existsSync(serverEnvPath)) return;
127	    writePrivateFile(envPath, readFileSync(serverEnvPath, "utf-8"));
128	    console.log(`  \x1b[2m♻ Migrated Electron secrets from ${serverEnvPath} to ${envPath}\x1b[0m`);
129	  } catch {
130	    // Ignore errors migrating server.env — fall back to normal env loading below.
131	  }
132	}
