148	  }
149	
150	  // Hermetic commands (real CLI smokes, migrations, recovery probes) may point
151	  // DATA_DIR at an isolated tree. Do not silently mix the user's default
152	  // credential env into that process when isolation is explicitly requested.
153	  if (process.env.OMNIROUTE_CLI_SKIP_DEFAULT_DATA_ENV !== "1") {
154	    addEnvPath(join(getDefaultDataDir(), ".env"));
155	  }
156	
157	  addEnvPath(join(process.cwd(), ".env"));
158	  // Skip the repo-checkout .env when explicitly requested (used by isolation tests
159	  // that need a deterministic environment without the development repo's defaults).
160	  if (process.env.OMNIROUTE_CLI_SKIP_REPO_ENV !== "1") {
161	    addEnvPath(join(ROOT, ".env"));
162	  }
163	
164	  const keyOrigin = new Map();
165	  const shadowed = new Map();
166	
167	  for (const envPath of envPaths) {
168	    try {
