171	        for (const line of content.split("\n")) {
172	          const trimmed = line.trim();
173	          if (!trimmed || trimmed.startsWith("#")) continue;
174	          const eqIdx = trimmed.indexOf("=");
175	          if (eqIdx > 0) {
176	            const key = trimmed.slice(0, eqIdx).trim();
