182	              // per key, whether the winner was an earlier file or the process
183	              // environment (#6194: a shell's own HOSTNAME beat the .env and the
184	              // server bound to the wrong address in silence).
185	              shadowed.set(key, { winner: keyOrigin.get(key) ?? null, loser: envPath });
186	            }
187	          }
188	        }
189	        loadedEnvPaths.push(envPath);
190	      }
191	    } catch (err) {
192	      console.warn(`  \x1b[33m⚠ Could not read ${envPath}: ${err?.message ?? err}\x1b[0m`);
193	    }
194	  }
195	
196	  for (const envPath of loadedEnvPaths) {
197	    console.log(`  \x1b[2m📋 Loaded env from ${envPath}\x1b[0m`);
198	  }
